import{_ as t,l as s,o,c as E,v as a,p as r,x as d,d as i,i as l,S}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"集合运算与 EXISTS","description":"","frontmatter":{"title":"集合运算与 EXISTS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/set-ops-exists.md","filePath":"cs/set-ops-exists.md","lastUpdated":1789023840000}'),T={name:"cs/set-ops-exists.md"};function n(N,e,p,I,h,A){const c=s("Mermaid");return o(),E("div",null,[e[1]||(e[1]=a('<h1 id="集合运算与-exists" tabindex="-1">集合运算与 EXISTS <a class="header-anchor" href="#集合运算与-exists" aria-label="Permalink to &quot;集合运算与 EXISTS&quot;">​</a></h1><div class="epigraph"><p>并交差是关系代数的原语；EXISTS 是演算里的存在量词。SQL 两者都给，指称要对齐，NULL 与包会把对齐撕开一条缝。</p><footer>—— 据 Codd 关系代数与元组演算；Date 对 EXISTS；Ramakrishnan and Gehrke 整理</footer></div><p><a href="/cs/recursive-cte">上一课</a>用迭代并逼近传递闭包。本课不重写不动点。缺口是日常查询里的<strong>集合级对照</strong>：<code>UNION</code>/<code>INTERSECT</code>/<code>EXCEPT</code>，以及 <code>EXISTS</code>/<code>NOT EXISTS</code>。主干代数课有并交差，SQL 声明课点到 <code>UNION</code>；进阶要把包版本、对应列、存在量化与半连接一次钉清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>用户写「在 A 不在 B」「A 与 B 都有的键」。用 <code>NOT IN</code> 子查询遇到 NULL 会得到 UNKNOWN，整句滤掉过多行——<a href="/cs/sql-null">三值</a> 已警告。<code>NOT EXISTS</code> 按行相关探测内层是否非空，对 NULL 更符合「不存在匹配」的直觉。缺口不是再讲嵌套语法，而是<strong>集合运算与存在量化何时同指称、何时必须分开</strong>。</p><p><code>UNION</code> 去重，<code>UNION ALL</code> 保留包计数。<code>INTERSECT</code>/<code>EXCEPT</code> 同样有 ALL 变体。对应列要可比较、模式对齐。集合运算两侧先投影到同一目，再做袋或集合运算。</p><p><span class="marginnote">Codd 的演算用 ∃ 表达连接与选择。SQL 的 <code>EXISTS (SELECT * FROM …)</code> 不关心投影列，只关心非空。半连接实现它；反半连接实现 <code>NOT EXISTS</code>。去相关课已用过这组算子，本课从语言对照补齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>集合运算：两输入关系（包）模式兼容 → 并/交/差。优化器可把 <code>EXCEPT</code> 变成反半连接或哈希差。<code>EXISTS</code>：对每个外层行求内层是否非空，允许内层一旦找到一行就停。<code>IN</code> 列表是等值存在，遇 NULL 走三值；能改写为半连接时必须复制该三值行为，否则指称错。</p><p>相关 <code>EXISTS</code> 与不相关 <code>EXISTS</code>：后者可先判一次真假；前者依赖外层。本课不把 <code>UNIQUE</code> 谓词、<code>MATCH</code> 的全部标准角落写完。</p>',10)),(o(),r(S,null,{default:d(()=>[l(c,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALG%5B%22%E5%B9%B6%20%2F%20%E4%BA%A4%20%2F%20%E5%B7%AE%22%5D%20--%3E%20BAG%5B%22ALL%3A%20%E5%8C%85%E8%AE%A1%E6%95%B0%22%5D%0A%20%20ALG%20--%3E%20SET%5B%22%E6%97%A0%20ALL%3A%20%E5%8E%BB%E9%87%8D%22%5D%0A%20%20EX%5B%22EXISTS%22%5D%20--%3E%20SJ%5B%22%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20NEX%5B%22NOT%20EXISTS%22%5D%20--%3E%20ASJ%5B%22%E5%8F%8D%E5%8D%8A%E8%BF%9E%E6%8E%A5%22%5D%0A%20%20INP%5B%22IN%20%2F%20NOT%20IN%22%5D%20--%3E%20TV%5B%22%E4%B8%89%E5%80%BC%E9%99%B7%E9%98%B1%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>执行上，哈希差与排序归并差对应两种物理形状，与连接算法同源：一边建哈希或两边排序。<code>EXISTS</code> 短路径：内层有索引时相关探测很便宜，这是去相关课「保留 NLJ」的例子。<code>UNION</code> 后的 <code>ORDER BY</code> 只对总结果排序，不能假设某一侧的序还在。</p><p>递归 CTE 的 <code>UNION</code> 与本课 <code>UNION</code> 同一代数，只是一侧在迭代中增长。本课不回头重讲停机。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把外连接引进来：外连接保留未匹配侧并填 NULL，与差、反半连接都不同。下一课专讲外连接与半连接的对照。也不把集合运算当完整性约束的替代——约束是后课触发器与声明约束。</p><p>后课默认：写「不存在」优先考虑 <code>NOT EXISTS</code> 或差，而不是 <code>NOT IN</code> 碰 NULL。集合运算是代数原语，存在量化是演算原语，计划上常汇合到半连接族。</p><p>包与集合必须在语句里显式选择（ALL 或否），不能靠引擎「顺便去重」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>UNION</code>/<code>INTERSECT</code>/<code>EXCEPT</code> 有集合与包两档；模式必须对齐。</li><li><code>EXISTS</code> 即半连接；<code>NOT IN</code> 与 <code>NOT EXISTS</code> 在 NULL 下不同指称。</li><li>外连接与半连接下一课，补「保留未匹配」。</li><li>出处：Codd；Date；Ramakrishnan and Gehrke。</li></ul>',9))])}const B=t(T,[["render",n]]);export{_ as __pageData,B as default};
